void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Time varying pixel color
    uv *= 40.0;
    uv = floor(uv)+smoothstep(0.5, 0.1+0.2*sin(iTime), fract(uv));


    vec3 col = 0.3 + 0.4*cos(iTime*2.0 + 5.0*cos(iTime*3.2) + uv.x*uv.xyx*0.25*sin(iTime*0.1) - uv.y*uv.xyx*0.1 + vec3(1, 1, 0));



    // Output to screen
    fragColor = vec4(col,1.0);
}
